mapper.select:
select answer_id, record_id, exam_id, question_id, question_type, question_order, standard_answer, student_answer, is_correct, question_score, actual_score, teacher_comment, checked_by, checked_time from edu_exam_answer where record_id in
#{recordId}
order by question_order asc, answer_id asc

mapper.update:
update edu_exam_answer
student_answer = #{studentAnswer}, is_correct = #{isCorrect}, actual_score = #{actualScore}, teacher_comment = #{teacherComment}, checked_by = #{checkedBy}, checked_time = #{checkedTime},
where answer_id = #{answerId}
